1172	// context, trace and attempt records produced so far, and never carries a
1173	// success result. Compensation for already-succeeded actions is attached by
1174	// withCompensation under the usual rules.
1175	function cancelledResult(state) {
1176	  return {
1177	    status: 'cancelled',
1178	    context: state.context,
1179	    trace: state.trace,
