1184	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1185	  const signal = resolveRunSignal(options);
1186	  const nodes = validateWorkflow(workflow);
1187	  verifyOperations(nodes, operations);
