    { id: 'done', type: 'end', result: 'finished' },
  ],
});

// 1. bare SAB
let r = await executeWorkflowAsync(wf(), {}, { op: () => new SharedArrayBuffer(8) });
console.log('bare SAB:', r.status, '|', r.error);

// 2. Uint8Array over SAB
r = await executeWorkflowAsync(wf(), {}, { op: () => new Uint8Array(new SharedArrayBuffer(4)) });
console.log('view SAB:', r.status, '|', r.error);

// 3. DataView over SAB nested in Map key / Set member / array / object
const sab = new SharedArrayBuffer(4);
r = await executeWorkflowAsync(wf(), {}, { op: () => ({ a: [new Set([new DataView(sab)])], m: new Map([[new Int32Array(sab), { x: new Uint8Array(sab) }]]) }) });
console.log('nested SAB:', r.status, '|', r.error);

// 4. plain ArrayBuffer accepted
r = await executeWorkflowAsync(wf(), {}, { op: () => ({ buf: new ArrayBuffer(4), bytes: new Uint8Array([9,8,7]) }) });
console.log('plain AB:', r.status, r.context.output.work.bytes instanceof Uint8Array, r.context.output.work.buf instanceof ArrayBuffer);

// 5. retry: SAB then normal value succeeds; output comes only from success
r = await executeWorkflowAsync(wf(true), {}, { op: (i,o,n,a) => a === 1 ? new SharedArrayBuffer(2) : 'fine' });
console.log('retry recover:', r.status, r.context.output.work, JSON.stringify(r.actionAttempts.map(x => [x.attempt, x.ok])));

// 6. Promise return of SAB
r = await executeWorkflowAsync(wf(), {}, { op: async () => new SharedArrayBuffer(2) });
console.log('promise SAB:', r.status, '|', r.error);
"

